const fs = require('fs');
const content = fs.readFileSync('/trajectory.txt', 'utf8');
const parts = content.split(/(<\|user\|>|<\|assistant\|>)/);
for (let i = 0; i < parts.length; i++) {
    if (parts[i] === '<|user|>' || parts[i] === '<|assistant|>') {
        console.log('MARKER:', parts[i]);
    } else if (parts[i]) {
        console.log('CONTENT (' + parts[i].length + ' chars):', JSON.stringify(parts[i].substring(0, 50)) + ' ... ' + JSON.stringify(parts[i].substring(parts[i].length - 50)));
    }
}
"

